const grid=document.querySelector('#product-grid');
function renderProducts(filter='all'){grid.innerHTML=products.filter(p=>filter==='all'||p.cat===filter).map(p=>`<article class="product-card"><span class="product-category">${p.label}</span><div class="product-image">${p.img?`<img src="assets/${p.img}" alt="${p.name}" loading="lazy">`:'<span class="app-mark" aria-hidden="true">RT<span style="font-size:25px;letter-spacing:-1px">app</span></span>'}</div><h3>${p.name}</h3><p>${p.desc}</p><a target="_blank" rel="noopener" href="https://wa.me/528116038103?text=${encodeURIComponent('Hola, me interesa '+p.name+' de RT Mobile')}">Cotizar equipo <span>↗</span></a></article>`).join('')}
renderProducts();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderProducts(b.dataset.filter)}));
document.querySelector('#year').textContent=new Date().getFullYear();
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;const toggle=document.querySelector('#motion-toggle');function setMotion(){document.body.classList.toggle('motion-paused',paused);toggle.setAttribute('aria-pressed',String(paused));toggle.setAttribute('aria-label',paused?'Activar animaciones':'Pausar animaciones');toggle.innerHTML=(paused?'▶':'Ⅱ')+' <span>Animación</span>'}setMotion();toggle.addEventListener('click',()=>{paused=!paused;setMotion()});reduced.addEventListener('change',e=>{paused=e.matches;setMotion()});
if('IntersectionObserver'in window){document.body.classList.add('js-motion');const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(x=>observer.observe(x))}
const canvas=document.querySelector('#signal'),ctx=canvas.getContext('2d');let width,height,phase=0,pointer={x:0,y:0};function resize(){width=canvas.clientWidth;height=canvas.clientHeight;const dpr=Math.min(devicePixelRatio,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}resize();window.addEventListener('resize',resize);document.querySelector('.hero').addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=(e.clientX-r.left)/width-.5;pointer.y=(e.clientY-r.top)/height-.5});
function draw(){ctx.clearRect(0,0,width,height);const cx=width*.77,cy=height*.57;for(let row=0;row<19;row++){ctx.beginPath();for(let col=0;col<32;col++){let x=(col-16)*42,y=(row-9)*39;let z=Math.sin(col*.26+phase)*22+Math.cos(row*.3+phase)*26;const a=-.35+pointer.x*.13;let px=x*Math.cos(a)-y*Math.sin(a),py=x*Math.sin(a)+y*Math.cos(a);const sx=cx+px,sy=cy+py*.48+z+pointer.y*15;col?ctx.lineTo(sx,sy):ctx.moveTo(sx,sy);if(col%3===0&&row%2===0){ctx.fillStyle='rgba(255,112,47,.38)';ctx.fillRect(sx,sy,2,2)}}ctx.strokeStyle='rgba(255,115,55,.075)';ctx.stroke()}const g=ctx.createLinearGradient(0,0,width,0);g.addColorStop(0,'#08090b');g.addColorStop(.36,'#08090bec');g.addColorStop(.7,'#08090b00');ctx.fillStyle=g;ctx.fillRect(0,0,width,height)}
let last=0;function animate(t){if(t-last>32){if(!paused&&!document.hidden){phase+=.012;draw()}last=t}requestAnimationFrame(animate)}draw();requestAnimationFrame(animate);
const dialog=document.querySelector('#demo-dialog'),content=document.querySelector('#demo-content');let routeTimer;function openDemo(type){clearInterval(routeTimer);document.querySelector('#demo-title').textContent=type==='video'?'El camino. Y la cabina.':'Cada movimiento, visible.';if(type==='video'){content.innerHTML='<div style="overflow:hidden;background:#050607"><img class="demo-image" src="assets/dash0-0.png" alt="Vista de ejemplo del camino y cabina del catálogo RT Mobile"></div><div class="camera-controls"><button class="active" data-view="both" aria-pressed="true">Vista dual</button><button data-view="front" aria-pressed="false">Camino</button><button data-view="cabin" aria-pressed="false">Cabina</button></div><p class="route-state">Imagen del catálogo. La transmisión en vivo se habilita con acceso a la plataforma.</p>';content.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{content.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const img=content.querySelector('img');img.style.width=b.dataset.view==='both'?'100%':'200%';img.style.maxWidth='none';img.style.transform=b.dataset.view==='cabin'?'translateX(-50%)':'none';img.style.maxHeight=b.dataset.view==='both'?'340px':'none'}))}else{content.innerHTML='<div class="gps-map"><span class="gps-caption">UNIDAD DEMO 01 · RECORRIDO SIMULADO</span><svg viewBox="0 0 700 290" aria-label="Diagrama de una ruta de ejemplo"><path id="route" d="M70 225 L170 225 Q210 225 210 185 L210 130 Q210 105 250 105 L400 105 Q445 105 445 150 L445 180 Q445 210 490 210 L625 210" fill="none" stroke="#ff6928" stroke-width="3"/><circle cx="70" cy="225" r="7" fill="#fff"/><circle cx="625" cy="210" r="7" fill="#fff"/><circle id="unit" class="gps-unit" r="11" cx="70" cy="225"/></svg></div><div class="camera-controls"><button id="run-route">Reproducir recorrido</button><button id="reset-route">Reiniciar</button></div><p class="route-state" id="route-state">Recorrido de ejemplo listo. Sin datos de una unidad real.</p>';let progress=0,running=false;const path=content.querySelector('#route'),unit=content.querySelector('#unit'),run=content.querySelector('#run-route');const move=()=>{const p=path.getPointAtLength(path.getTotalLength()*progress);unit.setAttribute('cx',p.x);unit.setAttribute('cy',p.y)};run.onclick=()=>{running=!running;if(progress>=1)progress=0;run.textContent=running?'Pausar recorrido':'Continuar recorrido'};content.querySelector('#reset-route').onclick=()=>{progress=0;running=false;move();run.textContent='Reproducir recorrido';content.querySelector('#route-state').textContent='Recorrido reiniciado. Datos de ejemplo.'};routeTimer=setInterval(()=>{if(!running||document.hidden)return;progress=Math.min(1,progress+.006);move();content.querySelector('#route-state').textContent='Recorrido simulado · '+Math.round(progress*100)+'% completado';if(progress===1){running=false;run.textContent='Repetir recorrido'}},60)}dialog.showModal()}
document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>openDemo(b.dataset.demo)));document.querySelector('.close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>clearInterval(routeTimer));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
